using Microsoft.EntityFrameworkCore;

// Cosmos DB provider context — fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed the default discriminator property from
        // "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must explicitly preserve the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
        // Existing documents have the compound format, so preserve it.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Fix 3: Cosmos DB provider no longer supports synchronous I/O.
// All sync calls (ToList(), SaveChanges(), First(), etc.) now throw.
// Use async equivalents instead.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.ToList();
    //   _db.SaveChanges();

    // AFTER:
    public async Task<List<Session>> GetSessionsAsync()
        => await _db.Sessions.ToListAsync();

    public async Task SaveAsync()
        => await _db.SaveChangesAsync();
}

